// Fonction simple pour obtenir une traduction
export const getAccountText = (lang, path) => {
  const keys = path.split('.');
  let value = accountTranslations[lang] || accountTranslations.fr;
  
  for (const key of keys) {
    value = value?.[key];
    if (!value) return path; // Retourne la clé si traduction manquante
  }
  
  return value;
};
